#include "field.hpp"
int main(int argc,char**argv){if(argc<3){cerr<<"usage: build_norm norm_input.txt output.txt [x_point_count]\n";return 2;}try{init();ifstream in(argv[1]);if(!in)throw runtime_error("cannot open input file");Pol P=readp(in),b3=readp(in),Q=readp(in);vector<Pol>U(5),V(5),W(5);for(auto&z:U)z=readp(in);for(auto&z:V)z=readp(in);for(auto&z:W)z=readp(in);F kl,km;in>>kl>>km;F ikl=inv(kl),zeta=power(25,NN/3);int nx=argc>3?atoi(argv[3]):115;if(nx<109)throw runtime_error("need at least 109 interpolation points");Pol xs;for(int x=0;xs.size()<nx;x++){int px=ev(P,x);if(px&&lg[px]%3==0&&ev(b3,x))xs.push_back(x);}Pol ss(34);iota(ss.begin(),ss.end(),0);Pol nus,ts;set<int>seen;for(int n=0;n<QF&&nus.size()<12;n++){int t=power(n,3);if(seen.insert(t).second){nus.push_back(n);ts.push_back(t);}}vector<vector<vector<int>>> values(12,vector<vector<int>>(34,vector<int>(nx)));
for(int ix=0;ix<nx;ix++){F x=xs[ix],px=ev(P,x),bx=ev(b3,x),qx=ev(Q,x),y=ex[lg[px]/3];F den=power(mul(power(px,24),power(bx,20)),3);F cc=mul(power(bx,3),power(px,3));vector<F>ue(5),ve(5),we(5);for(int j=0;j<5;j++){ue[j]=ev(U[j],x);ve[j]=ev(V[j],x);we[j]=ev(W[j],x);}for(int is=0;is<34;is++){F s=ss[is],lam=mul(sub(1,mul(km,s)),ikl);vector<F>ns(5);for(int j=0;j<5;j++)ns[j]=add(mul(lam,ue[j]),mul(s,ve[j]));for(int it=0;it<12;it++){F prod=1,yy=y;for(int k=0;k<3;k++){Pol poly(10);for(int j=0;j<5;j++){F a=add(ns[j],mul(mul(nus[it],yy),we[j]));poly[4-j]=mul(qx,a);poly[9-j]=a;}poly[0]=add(poly[0],cc);prod=mul(prod,disc(poly));yy=mul(yy,zeta);}values[it][is][ix]=mul(prod,inv(den));}}if(ix%20==0)cerr<<"x "<<ix<<"/"<<nx<<"\n";}
vector<vector<vector<int>>> cp(109,vector<vector<int>>(34,vector<int>(12)));for(int it=0;it<12;it++)for(int is=0;is<34;is++){Pol xsmall(xs.begin(),xs.begin()+109),vsmall(values[it][is].begin(),values[it][is].begin()+109);Pol p=interp(xsmall,vsmall);p.resize(109);for(int i=0;i<nx;i++)if(ev(p,xs[i])!=values[it][is][i])throw runtime_error("x degree");for(int i=0;i<109;i++)cp[i][is][it]=p[i];}
// Interpolate in t first then s. Save as x,s,t triples.
vector<vector<Pol>> ans(109,vector<Pol>(12));for(int i=0;i<109;i++){vector<Pol> tt;for(int is=0;is<34;is++){auto z=interp(ts,cp[i][is]);z.resize(12);tt.push_back(z);}for(int j=0;j<12;j++){Pol yy;for(int is=0;is<34;is++)yy.push_back(tt[is][j]);ans[i][j]=interp(ss,yy);if((int)ans[i][j].size()>34-3*j)throw runtime_error("total degree");}}
ofstream out(argv[2]);if(!out)throw runtime_error("cannot open output file");out<<"109 12\n";for(int i=0;i<109;i++)for(int j=0;j<12;j++)printp(out,ans[i][j]);cerr<<"DONE norm polynomial, all degree constraints passed\n";
return 0;}catch(exception&e){cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
